// @ts-nocheck - generated by scripts/port-hello-flowers.mjs from src/assets/loader/Hello With Flowers.html; edit that file, not this.
// Soft rig: every outline point is moved by a smooth field, so the drawing bends instead of
// being cut apart - the hand waves, the flowers sway, the eyes blink.
export const RIG=(function(){
  const TAU=Math.PI*2, D=Math.PI/180;
  const ss=(a,b,x)=>{const t=Math.min(1,Math.max(0,(x-a)/(b-a)));return t*t*(3-2*t)};
  const ease=x=>x<=0?0:x>=1?1:x*x*(3-2*x);
  const HC={x:712,y:342.5};
  const SHOULDER={x:499,y:416}, WRIST={x:213,y:289}, AX={x:-0.395,y:-0.919}, ELBOW={x:345,y:405}, SH2={x:490,y:425};
  const FOLD=24*Math.PI/180; // elbow bend brings the waving hand in beside the face
  const RSH={x:792,y:578};
  const CL=[[800,580],[810,650],[840,730],[900,790],[960,810],[1000,800]];
  const SMILE={x0:655,x1:821,y0:255,y1:409,cx:740};
  const E1={x0:728,x1:762,y0:225,y1:264,cx:745,cy:244.5}, E2={x0:769,x1:803,y0:241,y1:280,cx:786,cy:260.5};
  function nearCL(x,y){
    let best=1e9,bs=0,acc=0;
    for(let i=0;i<CL.length-1;i++){
      const [ax,ay]=CL[i],[bx,by]=CL[i+1],dx=bx-ax,dy=by-ay,len=Math.hypot(dx,dy);
      let t=((x-ax)*dx+(y-ay)*dy)/(len*len); t=Math.max(0,Math.min(1,t));
      const d=Math.hypot(x-(ax+t*dx),y-(ay+t*dy));
      if(d<best){best=d;bs=acc+t*len}
      acc+=len;
    }
    return [best,bs];
  }
  // per-point weights depend only on the original drawing, so compute them once
  function weights(x,y,tag){
    const dH=Math.hypot(x-HC.x,y-HC.y);
    let wa=0,wh=0,wr=0,wf=0,kind=0,we=0;
    if(tag==='body'||tag==='stemP'||tag==='stemY'||tag==='pink'||tag==='yellow'||tag==='moL'||tag==='moT'){
      if(x<525&&y<505){ wa=ss(232,330,dH); wh=ss(-25,35,(x-WRIST.x)*AX.x+(y-WRIST.y)*AX.y); we=wa*ss(75,235,Math.hypot(x-SH2.x,y-SH2.y)); }
      // flower arm: one smooth falloff from the shoulder, kept off the head and the legs
      if(tag==='pink'||tag==='yellow'||tag==='stemP'||tag==='stemY') wr=1;   // flowers and stems ride with the hand as one piece
      else if(x>768&&y>470&&y<1000) wr=ss(30,230,Math.hypot(x-RSH.x,y-RSH.y))*ss(236,262,dH);
    }
    if(tag==='pink'||tag==='yellow') wf=1; else if(tag==='stemP'||tag==='stemY') wf=ss(738,560,y);
    if(tag==='body'&&x>SMILE.x0&&x<SMILE.x1&&y>SMILE.y0&&y<SMILE.y1) kind=1;
    if(tag==='body'&&x>E1.x0&&x<E1.x1&&y>E1.y0&&y<E1.y1) kind=2;
    if(tag==='body'&&x>E2.x0&&x<E2.x1&&y>E2.y0&&y<E2.y1) kind=3;
    const wsw=ss(1072,640,y);                       // body sway fades out toward the planted feet
    const wk=(x<775&&y>600)?Math.exp(-Math.pow((y-860)/150,2)):0; // knees
    return [wa,wh,wr,wf,kind,wsw,wk,we];
  }
  const PALM={x:165,y:190};
  // motion lines: the pair on the side the hand is swinging toward flicks out and darkens, the other pair settles back
  function motion(t){
    const w=TAU/0.95, burst=0.6+0.4*ease(0.5+0.5*Math.sin(TAU*t/4.2)), sw=Math.sin(w*t);
    const pL=Math.pow(0.5+0.5*sw,1.6)*burst, pT=Math.pow(0.5-0.5*sw,1.6)*burst;
    return {op:{moL:0.15+0.85*pL, moT:0.15+0.85*pT}, push:{moL:-4+12*pL, moT:-4+12*pT}};
  }
  function rotP(x,y,a,c){const s=Math.sin(a),k=Math.cos(a),dx=x-c.x,dy=y-c.y;return [c.x+dx*k-dy*s,c.y+dx*s+dy*k]}
  function prepare(layers){
    return layers.map(L=>{const n=L.p.length/2,W=new Float32Array(n*8);
      for(let i=0;i<n;i++){const w=weights(L.p[2*i],L.p[2*i+1],L.tag);for(let j=0;j<8;j++)W[i*8+j]=w[j];}
      return {L,W,phase:L.tag==='yellow'||L.tag==='stemY'?0.9:0,mo:L.tag==='moL'||L.tag==='moT'?L.tag:null};});
  }
  let nextBlink=2.0, blinkStart=-1;
  function blink(t){
    if(t<blinkStart) {blinkStart=-1;nextBlink=t+1.5}
    if(blinkStart<0&&t>=nextBlink) blinkStart=t;
    if(blinkStart<0) return 1;
    const e=(t-blinkStart)/0.16;
    if(e>1){blinkStart=-1;nextBlink=t+2.8+Math.random()*2.6;return 1}
    return 1-0.92*Math.sin(Math.PI*e);
  }
  function state(t){
    const burst=0.6+0.4*ease(0.5+0.5*Math.sin(TAU*t/4.2));
    const w=TAU/0.95;
    const g=0; // smile stays in the drawing's default state
    return {
      armA:(-2.2*Math.sin(w*t-0.5)*burst)*D,   // slight shoulder sway, hand stays by the face
      handA:(-11*Math.sin(w*t)*burst)*D,     // the wave mostly comes from the wrist
      rA:(1.6*Math.sin(TAU*t/3.4))*D,
      sway:(ph)=>5.5*Math.sin(TAU*t/2.9+ph),
      swayY:(ph)=>-1.2*(1-Math.cos(TAU*t/2.9+ph)),
      bx:4*Math.sin(TAU*t/5.2), by:1.6*(1-Math.cos(TAU*t/2.6)),
      kx:2.2*Math.sin(TAU*t/5.2+0.8),
      g:g, b:blink(t)
    };
  }
  function frame(prep,t){
    const S=state(t), out=[];
    const M=motion(t);
    for(const {L,W,phase,mo} of prep){
      const p=L.p,c=L.c,n=p.length/2,q=new Array(n*2);
      const fx=S.sway(phase), fy=S.swayY(phase);
      for(let i=0;i<n;i++){
        let x=p[2*i],y=p[2*i+1]; const o=i*8;
        const wa=W[o],wh=W[o+1],wr=W[o+2],wf=W[o+3],kind=W[o+4],wsw=W[o+5],wk=W[o+6],we=W[o+7];
        if(kind===1){ // smile: corners lift and spread a little, like cheeks rising
          const u=Math.max(-1,Math.min(1,(x-740)/80)), g=S.g;
          x+=g*4*u; y+=-g*(1.5+6*u*u)+g*1.2*(1-u*u);
        } else if(kind>1){ // eyes: cheeks push up a touch when smiling, plus blinks
          const cy=kind===2?244.5:260.5, sq=(1-0.16*S.g)*S.b;
          y=cy+(y-cy)*sq-4*S.g; x+=(kind===2?-1:1)*0.8*S.g;
        }
        if(mo){ const dx=x-PALM.x,dy=y-PALM.y,len=Math.hypot(dx,dy)||1, push=M.push[mo]; x+=dx/len*push; y+=dy/len*push; }
        if(wf>0){ x+=fx*wf; y+=fy*wf; }
        if(wh>0){ [x,y]=rotP(x,y,S.handA*wh,WRIST); }
        if(we>0){ [x,y]=rotP(x,y,FOLD*we,ELBOW); }
        if(wa>0){ [x,y]=rotP(x,y,S.armA*wa,SHOULDER); }
        if(wr>0){ [x,y]=rotP(x,y,S.rA*wr,RSH); }
        if(wk>0){ x+=S.kx*wk; }
        if(wsw>0){ x+=S.bx*wsw; y+=S.by*wsw; }
        q[2*i]=x; q[2*i+1]=y;
      }
      let d='',k=0;
      for(const ch of c){
        if(ch==='Z'){d+='Z';continue}
        const m=ch==='C'?3:1; d+=ch;
        for(let j=0;j<m;j++){d+=q[k].toFixed(1)+' '+q[k+1].toFixed(1)+' ';k+=2}
      }
      out.push(d);
    }
    return out;
  }
  // the mouth: your smile outline, blended point by point from a small rounded smile to the full shape
  function smileD(SM,t){
    const S=state(t), g=S.g, n=SM.full.length, pts=new Array(n);
    for(let i=0;i<n;i++){
      const a=SM.small[i], b=SM.full[i];
      pts[i]=[a[0]+(b[0]-a[0])*g+S.bx, a[1]+(b[1]-a[1])*g+S.by];
    }
    let d='M'+pts[0][0].toFixed(1)+' '+pts[0][1].toFixed(1);
    for(let i=0;i<n;i++){
      const p0=pts[(i-1+n)%n],p1=pts[i],p2=pts[(i+1)%n],p3=pts[(i+2)%n];
      d+='C'+(p1[0]+(p2[0]-p0[0])/6).toFixed(1)+' '+(p1[1]+(p2[1]-p0[1])/6).toFixed(1)+' '+
             (p2[0]-(p3[0]-p1[0])/6).toFixed(1)+' '+(p2[1]-(p3[1]-p1[1])/6).toFixed(1)+' '+
             p2[0].toFixed(1)+' '+p2[1].toFixed(1);
    }
    return d+'Z';
  }
  return {prepare,frame,smileD,motion};
})();
